  if(id==='budget'){
    if(data.key<period())throw new Error('Historical budgets are retained. Record an explicit transaction correction instead.');
    const alloc=Object.fromEntries(Object.entries(d).filter(([k])=>k.startsWith('alloc:')).map(([k,v])=>[k.slice(6),C.money(v)])),salary=C.money(d.salary);
    return commit(C.setBudget(state,{key:data.key,salary,alloc}));
  }
  if(id==='category')return commit(C.addCategory(state,{name:d.name,type:d.type}));
  if(id==='obligation')return commit(C.addSchedule(state,{name:d.name,kind:d.kind,amount:C.money(d.amount),date:d.date,account:d.account,debtAccount:d.debtAccount||'',budgetCategory:d.budgetCategory||'',recurrence:d.repeat!=='once'?{unit:d.repeat,interval:Number(d.interval),until:d.until||''}:null}));
  if(id==='balance-review')return commit(C.reviewReconciliation(state,{id:data.id,note:d.note}),'Explanation saved; original balance difference retained');
  if(id==='outside-given')return commit(C.giveOutside(state,{name:d.name,kind:d.kind,amount:C.money(d.amount),account:d.account,date:d.date,note:d.note,due:d.due}),'Outgoing money and its record saved together');
